import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from '@/lib/utils'

/*
 * GENERATED BY `shadcn add table`, RETUNED TO THIS APP AND GIVEN ONE VARIANT.
 *
 * What it replaces is not a component -- it is five GLOBAL ELEMENT SELECTORS.
 * `table`, `th`, `td`, `th:first-child, td:first-child` and
 * `tbody tr:last-child td` set alignment, padding, tabular numerals, nowrap
 * and a rule on every cell in the application, and the consequence shows up
 * in the markup: because the global default was RIGHT, left-alignment was the
 * exception, spelled `className="l"` -- `text-align: left !important` -- at
 * thirty-six call sites. After this the default is left, which is the
 * browser's, and RIGHT is the exception, which is the five money columns.
 * The `!important` goes with it.
 *
 * `level` is the one variant, and it is structural rather than decorative.
 * This app nests tables three deep -- a table on a route, a journal inside
 * one of its cells, a movements table inside one of THOSE cells -- and each
 * level is a step quieter: smaller type, tighter rows, and headers that stop
 * being sentence-case labels and become uppercase eyebrows. That was three
 * hand-written recipes; it is one scale now.
 */

const tableVariants = cva('w-full caption-bottom border-collapse', {
  variants: {
    level: {
      /** On a route. Headers are labels, in the voice of the page. */
      page: 'text-lg [&_th]:px-2.5 [&_th]:py-2 [&_th]:font-semibold [&_th]:text-secondary-text [&_td]:px-2.5 [&_td]:py-2.25',
      /** Inside a cell of a `page` table. Headers become eyebrows. */
      nested:
        'text-md [&_th]:px-3 [&_th]:py-2.25 [&_th]:text-xs [&_th]:font-semibold [&_th]:uppercase [&_th]:tracking-caps [&_th]:text-muted-text [&_td]:px-3 [&_td]:py-2.25 [&_td]:align-top',
      /** Inside a cell of a `nested` table. The quietest level there is. */
      inner:
        'text-base [&_th]:px-3 [&_th]:py-2 [&_th]:text-xs [&_th]:font-semibold [&_th]:uppercase [&_th]:tracking-caps [&_th]:text-muted-text [&_td]:px-3 [&_td]:py-1.75',
    },
  },
  defaultVariants: { level: 'page' },
})

/**
 * `scroll` is OPT-IN, where upstream wraps unconditionally.
 *
 * Only the outermost table on a page needs it. "A table wider than its panel
 * scrolls INSIDE the panel instead of spilling past its border -- which is
 * what hid the whole BALANCE column, and with it the figure that proves no
 * row was dropped." The nested tables sit in a `<td>` of the table above
 * them, so the cell is already that wide and their own overflow never fires;
 * measured, `scrollWidth` equals `clientWidth` at every viewport. Wrapping
 * them anyway would add two clipping ancestors for nothing, in an app whose
 * help bubble has been cut in half by exactly that once already.
 *
 * The scrollbar is PERMANENT on purpose: "a money column off the right edge
 * has to be discoverable, and macOS hides its overlay scrollbar until
 * something moves. A thin permanent one says the table continues." Any
 * replacement that reveals it on hover has regressed it. iOS Safari renders
 * no `::-webkit-scrollbar` and ignores `scrollbar-color`, so a phone still
 * gets no cue; the answer there is a sticky right-hand column, not a louder
 * cue, and it is still open.
 */
function Table({
  className,
  level,
  scroll = false,
  ...props
}: React.ComponentProps<"table"> &
  VariantProps<typeof tableVariants> & { scroll?: boolean }) {
  const table = (
    <table
      data-slot="table"
      className={cn(tableVariants({ level }), className)}
      {...props}
    />
  )
  if (!scroll) return table
  return (
    <div
      data-slot="table-container"
      className="relative w-full overflow-x-auto [scrollbar-color:var(--color-border-strong)_transparent] [scrollbar-width:thin] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border-strong [&::-webkit-scrollbar]:h-2"
    >
      {table}
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("[&_tr]:border-b [&_tr]:border-border", className)}
      {...props}
    />
  )
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  )
}

/*
 * TWO THINGS ARE DELIBERATELY NOT HERE, both from upstream's `TableRow`.
 *
 * `hover:bg-muted/50` -- this app's row hover has always been a solid
 * `--surface-0`, and half alpha over the card is a different colour. More
 * importantly the hover belongs only to rows that DO something: upstream
 * tints the header row and the detail row too, which says "clickable" about
 * two things that are not.
 *
 * `has-aria-expanded:bg-muted/50` -- every `<Help>` button carries
 * `aria-expanded`, and help buttons live inside `<th>` and inside a movement
 * row's first cell. So pinning a help bubble would tint its header row or its
 * movement row, for no reason a reader could work out. The caret button this
 * unit adds carries `aria-expanded` by design, which would tint every open
 * row as well -- arguably wanted, never a behaviour of this app, and so a
 * decision rather than a default.
 */
function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn("border-b border-border", className)}
      {...props}
    />
  )
}

/** A row you can open. The hover is the affordance; the caret is the control. */
function TableRowButton({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn("cursor-pointer border-b border-border hover:bg-surface-0", className)}
      {...props}
    />
  )
}

function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      scope="col"
      className={cn("text-left align-middle whitespace-nowrap", className)}
      {...props}
    />
  )
}

/*
 * `tabular-nums` on EVERY cell, not only the money ones, because that is what
 * the global `td` rule did and a date column reads as a column for the same
 * reason a balance column does: `10/08/2026` over `21/09/2026` only lines up
 * if the digits are one width.
 */
function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn("text-left align-middle whitespace-nowrap tabular-nums", className)}
      {...props}
    />
  )
}

function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("mt-4 text-base text-muted-text", className)}
      {...props}
    />
  )
}

export {
  Table,
  TableHeader,
  TableBody,
  TableHead,
  TableRow,
  TableRowButton,
  TableCell,
  TableCaption,
}
